const D = { density: .55, energy: .6, speed: 1, turb: .6, scale: 1, buoyancy: .6, hue: 32, x: .5, y: .82, style: 'incense', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, u = Math.min(W, H);
const clp = (v,a,b)=> v<a?a:v>b?b:v;
const style = P.style, pencil = style === 'pencil-smoke';
const CAP = 1800, BW = 200, BH = Math.max(2, Math.round(BW * H / W));

function hsb2rgb(h,s,b){
  h = ((h%360)+360)%360; s = clp(s,0,100)/100; b = clp(b,0,100)/100;
  const c = b*s, x = c*(1 - Math.abs((h/60)%2 - 1)), m = b - c;
  let r,g,bl;
  if (h<60){ r=c; g=x; bl=0; } else if (h<120){ r=x; g=c; bl=0; }
  else if (h<180){ r=0; g=c; bl=x; } else if (h<240){ r=0; g=x; bl=c; }
  else if (h<300){ r=x; g=0; bl=c; } else { r=c; g=0; bl=x; }
  return [(r+m)*255, (g+m)*255, (bl+m)*255];
}

// coarse smoke feedback buffer (fixed width, aspect-matched height) — upscale = free blur
if (!S.buf || S.bh !== BH){
  if (S.buf && S.buf.remove) S.buf.remove();
  S.buf = createGraphics(BW, BH); S.buf.pixelDensity(1); S.buf.background(0);
  S.bh = BH; S.bgKey = null;
}
// particle pool (typed arrays)
if (!S.px){
  S.px = new Float32Array(CAP); S.py = new Float32Array(CAP);
  S.vx = new Float32Array(CAP); S.vy = new Float32Array(CAP);
  S.age = new Float32Array(CAP); S.life = new Float32Array(CAP); S.rnd = new Float32Array(CAP);
  for (let i=0;i<CAP;i++){ S.age[i] = 1e9; S.life[i] = 1; }
  S.rc = 1;
}
// seed rebuild: noise offsets + hash counter
const fr = i => { const s = Math.sin(i*127.1 + (P.seed|0)*311.7) * 43758.5453; return s - Math.floor(s); };
if (S.seedUsed !== (P.seed|0)){
  S.seedUsed = P.seed|0;
  S.so = fr(3)*100; S.so2 = fr(7)*100; S.so3 = fr(11)*40; S.rc = (P.seed|0)*131 + 7; S.bgKey = null;
}

const sec = K.section||0, intn = (K.intensity!=null?K.intensity:.6);
const secHue = sec*6;

// ambient gradient ground (rebuilt only on size/style/hue/seed change) — luminance floor + mood
const hueBucket = Math.round(P.hue/14);
const bgKey = BH+':'+style+':'+hueBucket+':'+S.seedUsed;
if (!S.bg || S.bgKey !== bgKey){
  if (S.bg && S.bg.remove) S.bg.remove();
  S.bg = createGraphics(BW, BH); S.bg.pixelDensity(1); S.bg.noStroke();
  let tH,tS,tB, bH,bS,bB;
  if (style==='colored-vapor'){ tH=248; tS=52; tB=9; bH=192; bS=44; bB=20; }
  else if (style==='volcanic'){ tH=8; tS=48; tB=6; bH=20; bS=72; bB=24; }
  else if (style==='ghost'){ tH=222; tS=20; tB=7; bH=210; bS=12; bB=18; }
  else if (pencil){ tH=0; tS=0; tB=8; bH=0; bS=0; bB=19; }
  else { tH=268; tS=48; tB=8; bH=(P.hue-6+360)%360; bS=58; bB=22; }
  const wob = (fr(21)-0.5)*10;
  for (let j=0;j<BH;j++){
    const f = j/(BH-1), ff = f*f*1.15;
    const h = tH + (bH-tH)*f + wob*f;
    const s = tS + (bS-tS)*f;
    const b = tB + (bB-tB)*Math.min(1,ff);
    const rgb = hsb2rgb(h, s, b);
    S.bg.fill(rgb[0], rgb[1], rgb[2]); S.bg.rect(0, j, BW, 1);
  }
  S.bgKey = bgKey;
}

// wandering emitter at the base of the column — perpetual sway = motion floor
const exN = clp(P.x + Math.cos(K.t*0.13)*0.03, 0.02, 0.98);
const eyN = clp(P.y + Math.sin(K.t*0.09)*0.015, 0.05, 0.99);
const ex = exN*BW, ey = eyN*BH;

// shared curl-noise velocity kernel (divergence-free; seed folded into coords, drift on K.t)
const spF = 0.02 / clp(P.scale, 0.35, 3), eps = 1.5;
const zt = K.t*(0.05 + P.speed*0.06) + S.so3;
const ns = (x,y)=> noise(x*spF + S.so, y*spF + S.so2, zt);
const curl = (x,y)=> Math.atan2(-(ns(x+eps,y)-ns(x-eps,y)), ns(x,y+eps)-ns(x,y-eps));

// dynamics (audio + pulse blended ON TOP of clk baseline)
const pulse = K.pulse||0, swell = K.swell||0;
const turbA = (0.15 + P.turb*0.8) * (0.9 + intn*0.4) * (1 + swell*0.25 + A.lowmid*0.7);
const riseA = (0.25 + P.buoyancy*0.85) * (1 + pulse*0.2*P.energy + A.bass*0.5);
const drag = 0.86, spd = 0.7 + P.speed*0.7, lifeBase = 120;
const spreadX = BW*(0.02 + P.scale*0.025 + P.density*0.022), spreadY = BH*0.02;
const briBoost = 1 + A.rms*0.6 + pulse*0.12;
const baseAlpha = 17 + P.energy*38;
const radE = 0.82 + P.energy*0.42;

function spawn(i){
  const a1 = fr(S.rc++), a2 = fr(S.rc++), a3 = fr(S.rc++), a4 = fr(S.rc++);
  S.px[i] = ex + (a1*2-1)*spreadX;
  S.py[i] = ey + a2*spreadY;
  S.vx[i] = (a3*2-1)*0.25;
  S.vy[i] = -(0.4 + a4*0.5)*riseA;
  S.age[i] = 0;
  S.life[i] = lifeBase*(0.55 + a1*0.9);
  S.rnd[i] = a2;
}

const activeN = Math.min(CAP, Math.round(200 + P.density*1400));

S.buf.push();
S.buf.blendMode(BLEND); S.buf.noStroke();
S.buf.fill(0, 0, 0, 22 + P.density*20);            // exponential fade toward black
S.buf.rect(0, 0, BW, BH);
S.buf.blendMode(ADD);
if (!pencil) S.buf.noStroke();

for (let i=0;i<activeN;i++){
  if (S.age[i] >= S.life[i] || S.py[i] < -6 || S.px[i] < -8 || S.px[i] > BW+8) spawn(i);
  const px = S.px[i], py = S.py[i];
  const a = curl(px, py);
  const f = clp(S.age[i]/S.life[i], 0, 1);
  const tvx = Math.cos(a)*turbA;
  const tvy = Math.sin(a)*turbA - riseA*(0.4 + (1-f)*1.1);   // buoyancy cools with age -> disperses
  const vx = S.vx[i]*drag + tvx*(1-drag);
  const vy = S.vy[i]*drag + tvy*(1-drag);
  S.vx[i] = vx; S.vy[i] = vy;
  S.px[i] = px + vx*spd; S.py[i] = py + vy*spd;
  S.age[i] += spd;

  let h,sa,br;
  if (style==='colored-vapor'){ h = (S.rnd[i]<0.5?185:308) + secHue + f*22; sa = 82-f*30; br = 92-f*36; }
  else if (style==='volcanic'){ h = 28 - f*20 + secHue*0.3; sa = 90-f*22; br = 100-f*74; }
  else if (style==='ghost'){ h = 205 + secHue*0.4; sa = 6+f*9; br = 97-f*44; }
  else if (pencil){ h = 0; sa = 0; br = 74-f*42; }
  else { h = P.hue + f*243 + secHue; sa = 86-f*54; br = 95-f*42; }   // incense: amber -> grey-violet
  const rgb = hsb2rgb(h, sa, br);
  const al = clp(baseAlpha*(1 - f*0.5)*briBoost, 0, 205);
  const rad = (1.4 + f*8.5)*(0.55 + P.scale*0.7)*radE;

  if (pencil){
    const vl = Math.hypot(vx, vy) || 1e-3, dx = vx/vl, dy = vy/vl, ln = rad*1.4;
    S.buf.stroke(rgb[0], rgb[1], rgb[2], al*0.85); S.buf.strokeWeight(0.8 + P.scale*0.6);
    S.buf.line(px - dx*ln, py - dy*ln, px + dx*ln, py + dy*ln);
  } else {
    S.buf.fill(rgb[0], rgb[1], rgb[2], al);
    S.buf.ellipse(px, py, rad, rad);
  }
}
S.buf.blendMode(BLEND);
S.buf.pop();

// ---- composite to main canvas ----
const ta = clp(P.alpha, 0, 100);
push();
if (ta < 100) tint(0, 0, 100, ta);
image(S.bg, 0, 0, W, H);                              // opaque ground (clears frame at alpha 100)
blendMode(ADD);
if (ta < 100) tint(0, 0, 100, ta);
image(S.buf, 0, 0, W, H);                             // upscaled soft smoke
noTint();
// warm base glow following the emitter (few soft ADD shapes)
const gH = pencil?0:(style==='ghost'?205:style==='volcanic'?20:style==='colored-vapor'?300:P.hue);
const gS = pencil?0:(style==='ghost'?14:78);
noStroke();
for (let k=0;k<3;k++){
  const rr = u*(0.09 + k*0.055);
  fill((((gH+secHue)%360)+360)%360, gS, 88, (9 + P.energy*13)*(1 - k*0.28)*(ta/100));
  ellipse(exN*W, eyN*H, rr*1.7, rr);
}
blendMode(BLEND);
pop();
